// SPDX-License-Identifier: Apache-2.0
pragma solidity >=0.8.0 <0.9.0;

import "./HederaTokenService.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

abstract contract KeyHelperUpgradeable is Initializable {

    error InvalidKeyValueType();

    /// @custom:storage-location erc7201:usdt0.storage.keyhelper
    struct KeyHelperStorage {
        mapping(KeyType => uint256) keyTypes;
    }

    // keccak256(abi.encode(uint256(keccak256("usdt0.storage.keyhelper")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant KEYHELPER_STORAGE_LOCATION = 0xf8f48d733279569f0de338c1e4c67f1ddd3eda3353f6c044a302fc5878538400;

    /**
     * @dev Retrieves the KeyHelperStorage struct from the designated storage slot.
     * @return $ The storage reference to KeyHelperStorage
     */
    function _getStorage() private pure returns (KeyHelperStorage storage $) {
        assembly {
            $.slot := KEYHELPER_STORAGE_LOCATION
        }
    }

    enum KeyType {
        ADMIN,
        KYC,
        FREEZE,
        WIPE,
        SUPPLY,
        FEE,
        PAUSE
    }
    enum KeyValueType {
        INHERIT_ACCOUNT_KEY,
        CONTRACT_ID,
        ED25519,
        SECP256K1,
        DELEGATABLE_CONTRACT_ID
    }

    /**
     * @dev Initializes the KeyHelper contract.
     * @notice This function should be called during contract initialization.
     */
    function __KeyHelper_init() internal onlyInitializing {
        __KeyHelper_init_unchained();
    }

    /**
     * @dev Initializes the KeyHelper contract without calling parent initializers.
     * @notice Sets up the mapping of KeyType enums to their corresponding bit flags for Hedera token key types.
     */
    function __KeyHelper_init_unchained() internal onlyInitializing {
        KeyHelperStorage storage $ = _getStorage();
        $.keyTypes[KeyType.ADMIN] = 1 << 0;
        $.keyTypes[KeyType.KYC] = 1 << 1;
        $.keyTypes[KeyType.FREEZE] = 1 << 2;
        $.keyTypes[KeyType.WIPE] = 1 << 3;
        $.keyTypes[KeyType.SUPPLY] = 1 << 4;
        $.keyTypes[KeyType.FEE] = 1 << 5;
        $.keyTypes[KeyType.PAUSE] = 1 << 6;
    }

    /**
     * @dev Creates a TokenKey struct for a specific key type with a cryptographic key.
     * @param keyType The type of key (ADMIN, KYC, FREEZE, etc.)
     * @param keyValueType The type of key value (ED25519, SECP256K1, etc.)
     * @param key The cryptographic key bytes
     * @return tokenKey The constructed TokenKey struct
     */
    function getSingleKey(
        KeyType keyType,
        KeyValueType keyValueType,
        bytes memory key
    ) internal view returns (IHederaTokenService.TokenKey memory tokenKey) {
        tokenKey = IHederaTokenService.TokenKey(
            getKeyType(keyType),
            getKeyValueType(keyValueType, key)
        );
    }

    /**
     * @dev Creates a TokenKey struct for a specific key type with a contract address.
     * @param keyType The type of key (ADMIN, KYC, FREEZE, etc.)
     * @param keyValueType The type of key value (CONTRACT_ID or DELEGATABLE_CONTRACT_ID)
     * @param contractAddress The contract address to use as the key
     * @return tokenKey The constructed TokenKey struct
     */
    function getSingleKey(
        KeyType keyType,
        KeyValueType keyValueType,
        address contractAddress
    ) internal view returns (IHederaTokenService.TokenKey memory tokenKey) {
        tokenKey = IHederaTokenService.TokenKey(
            getKeyType(keyType),
            getKeyValueTypeForContract(keyValueType, contractAddress)
        );
    }

    /**
     * @dev Retrieves the bit flag value for a given key type.
     * @param keyType The key type to look up
     * @return The bit flag value corresponding to the key type
     */
    function getKeyType(KeyType keyType) internal view returns (uint256) {
        KeyHelperStorage storage $ = _getStorage();
        return $.keyTypes[keyType];
    }

    /**
     * @dev Constructs a KeyValue struct based on the specified key value type and cryptographic key.
     * @param keyValueType The type of key value to create
     * @param key The cryptographic key bytes (used for ED25519 and SECP256K1 types)
     * @return keyValue The constructed KeyValue struct
     * @notice Reverts with InvalidKeyValueType if an unsupported key value type is provided
     */
    function getKeyValueType(
        KeyValueType keyValueType,
        bytes memory key
    ) internal pure returns (IHederaTokenService.KeyValue memory keyValue) {
        if (keyValueType == KeyValueType.INHERIT_ACCOUNT_KEY) {
            keyValue.inheritAccountKey = true;
        } else if (keyValueType == KeyValueType.ED25519) {
            keyValue.ed25519 = key;
        } else if (keyValueType == KeyValueType.SECP256K1) {
            keyValue.ECDSA_secp256k1 = key;
        } else {
            revert InvalidKeyValueType();
        }
    }

    /**
     * @dev Constructs a KeyValue struct for contract-based keys.
     * @param keyValueType The type of key value (must be CONTRACT_ID or DELEGATABLE_CONTRACT_ID)
     * @param contractAddress The contract address to use as the key
     * @return keyValue The constructed KeyValue struct
     * @notice Reverts with InvalidKeyValueType if a cryptographic key type (ED25519/SECP256K1) is provided
     */
    function getKeyValueTypeForContract(
        KeyValueType keyValueType,
        address contractAddress
    ) internal pure returns (IHederaTokenService.KeyValue memory keyValue) {
        if (keyValueType == KeyValueType.CONTRACT_ID) {
            keyValue.contractId = contractAddress;
        } else if (keyValueType == KeyValueType.DELEGATABLE_CONTRACT_ID) {
            keyValue.delegatableContractId = contractAddress;
        } else {
            revert InvalidKeyValueType();
        }
    }
}

contracts/HTSConnectorUpgradeable.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.22;

import { OFTCoreUpgradeable } from "@layerzerolabs/oft-evm-upgradeable/contracts/oft/OFTCoreUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import { HederaTokenService } from "./hts/HederaTokenService.sol";
import { IHederaTokenService } from "./hts/IHederaTokenService.sol";
import { KeyHelperUpgradeable} from "./hts/KeyHelperUpgradeable.sol";

/**
 * @title HTS Connector Upgradeable
 * @dev Upgradeable HTS Connector that creates its own HTS token and extends the functionality of the OFTCore contract.
 */
contract HTSConnectorUpgradeable is OwnableUpgradeable, OFTCoreUpgradeable, KeyHelperUpgradeable, HederaTokenService {

    error AmountExceedsInt64Range();
    error HTSTransferFailed();
    error HTSBurnFailed();
    error HTSMintFailed();
    error HTSTokenCreationFailed();

    event MintedToken(int64 newTotalSupply, uint256 _amountLD, address indexed to);
    event BurnedToken(int64 newTotalSupply, uint256 _amountLD, address indexed from); 
    event TokenCreated(address tokenAddress);

    /// @custom:storage-location erc7201:usdt0.storage.htsconnector
    struct HTSConnectorStorage {
        address htsTokenAddress;
        string _tokenName;
        string _tokenSymbol;
        int64 _tokenInitialTotalSupply;
        bytes _adminKey;
        address _safeWallet;
    }

    // keccak256(abi.encode(uint256(keccak256("usdt0.storage.htsconnector")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant HTSCONNECTOR_STORAGE_LOCATION = 0xa0902b535f35d140c0a624a863b38e1f2ddeb60ed857929d013466e495be5000;

    /**
     * @dev Retrieves the HTSConnectorStorage struct from the designated storage slot.
     * @return $ The storage reference to HTSConnectorStorage
     */
    function _getHtsConnectorStorage() private pure returns (HTSConnectorStorage storage $) {
        assembly {
            $.slot := HTSCONNECTOR_STORAGE_LOCATION
        }
    }

    uint8 private constant _DECIMALS = 6;
    int64 private constant _AUTO_RENEW_PERIOD = 8000000;

    error TokenAlreadyCreated();
    error TokenNotCreated();

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address _lzEndpoint) OFTCoreUpgradeable(_DECIMALS, _lzEndpoint) {
        _disableInitializers();
    }

    function htsTokenAddress() public view returns (address) {
        HTSConnectorStorage storage $ = _getHtsConnectorStorage();
        return $.htsTokenAddress;
    }

    /**
     * @dev Initializer for the HTS Connector contract.
     * @param _name The name of HTS token
     * @param _symbol The symbol of HTS token
     * @param adminKey The admin key for the token
     * @param _delegate The delegate capable of making OApp configurations inside of the endpoint.
     * @param _safeWalletAddr The safe wallet address for freeze/wipe keys
     */
    function initialize(
        string memory _name,
        string memory _symbol,
        int64 /* _initialTotalSupply */ ,
        bytes memory adminKey,
        address _delegate,
        address _safeWalletAddr
    ) external initializer {
        __OFTCore_init(_delegate);
        __Ownable_init(_delegate);
        __KeyHelper_init();

        HTSConnectorStorage storage $ = _getHtsConnectorStorage();

        // Store parameters for later token creation
        $._tokenName = _name;
        $._tokenSymbol = _symbol;
        $._tokenInitialTotalSupply = 0;
        $._adminKey = adminKey;
        $._safeWallet = _safeWalletAddr;
    }

    /**
     * @dev Creates the HTS token. Can only be called once and requires HBAR to be sent.
     */
    function createHTSToken() external payable {
        if (isTokenCreated()) {
            revert TokenAlreadyCreated();
        }

        HTSConnectorStorage storage $ = _getHtsConnectorStorage();

        // Create HTS token with stored configuration
        IHederaTokenService.TokenKey[] memory keys = new IHederaTokenService.TokenKey[](4);
        keys[0] = getSingleKey(
            KeyType.ADMIN, 
            KeyValueType.SECP256K1, 
            $._adminKey
        );
        keys[1] = getSingleKey(
            KeyType.FREEZE,
            KeyValueType.CONTRACT_ID,
            $._safeWallet
        );
        keys[2] = getSingleKey(
            KeyType.WIPE,
            KeyValueType.CONTRACT_ID,
            $._safeWallet
        );
        keys[3] = getSingleKey(
            KeyType.SUPPLY,
            KeyValueType.INHERIT_ACCOUNT_KEY,
            bytes("")
        );

        IHederaTokenService.Expiry memory expiry = IHederaTokenService.Expiry(0, address(this), _AUTO_RENEW_PERIOD);
        IHederaTokenService.HederaToken memory hederaToken = IHederaTokenService.HederaToken(
            $._tokenName, $._tokenSymbol, address(this), "", false, 0, false, keys, expiry
        );

        (int256 responseCode, address tokenAddress) = HederaTokenService.createFungibleToken(
            hederaToken, $._tokenInitialTotalSupply, int32(uint32(_DECIMALS))
        );
        if (responseCode != HederaTokenService.SUCCESS_CODE) {
            revert HTSTokenCreationFailed();
        }

        $.htsTokenAddress = tokenAddress;

        emit TokenCreated(tokenAddress);
    }

    /**
     * @dev Retrieves the address of the underlying HTS implementation.
     * @return The address of the HTS token.
     */
    function token() public view returns (address) {
        return htsTokenAddress();
    }

    /**
     * @notice Indicates whether the HTS Connector contract requires approval of the 'token()' to send.
     * @return requiresApproval Needs approval of the underlying token implementation.
     */
    function approvalRequired() external pure virtual returns (bool) {
        return true;
    }

    /**
     * @dev Returns whether the HTS token has been created
     */
    function isTokenCreated() public view returns (bool) {
        return htsTokenAddress() != address(0);
    }

    /**
     * @dev Modifier to ensure the HTS token has been created before execution
     */
    modifier onlyWhenTokenCreated() {
        if (htsTokenAddress() == address(0)) {
            revert TokenNotCreated();
        }
        _;
    }

    /**
     * @dev Burns tokens from the sender's specified balance.
     * @param _from The address to debit the tokens from.
     * @param _amountLD The amount of tokens to send in local decimals.
     * @param _minAmountLD The minimum amount to send in local decimals.
     * @param _dstEid The destination chain ID.
     * @return amountSentLD The amount sent in local decimals.
     * @return amountReceivedLD The amount received in local decimals on the remote.
     */
    function _debit(
        address _from,
        uint256 _amountLD,
        uint256 _minAmountLD,
        uint32 _dstEid
    ) internal virtual override onlyWhenTokenCreated returns (uint256 amountSentLD, uint256 amountReceivedLD) {
        if (_amountLD > uint64(type(int64).max)) {
            revert AmountExceedsInt64Range();
        }

        (amountSentLD, amountReceivedLD) = _debitView(_amountLD, _minAmountLD, _dstEid);

        int256 transferResponse = HederaTokenService.transferToken(htsTokenAddress(), _from, address(this), int64(uint64(amountSentLD)));
        if (transferResponse != HederaTokenService.SUCCESS_CODE) {
            revert HTSTransferFailed();
        }

        (int256 response,) = HederaTokenService.burnToken(htsTokenAddress(), int64(uint64(amountSentLD)), new int64[](0));
        if (response != HederaTokenService.SUCCESS_CODE) {
            revert HTSBurnFailed();
        }
    }

    /**
     * @dev Credits tokens to the specified address.
     * @param _to The address to credit the tokens to.
     * @param _amountLD The amount of tokens to credit in local decimals.
     * @dev _srcEid The source chain ID.
     * @return amountReceivedLD The amount of tokens ACTUALLY received in local decimals.
     */
    function _credit(
        address _to,
        uint256 _amountLD,
        uint32 /*_srcEid*/
    ) internal virtual override onlyWhenTokenCreated returns (uint256) {
        if (_amountLD > uint64(type(int64).max)) {
            revert AmountExceedsInt64Range();
        }

        (int256 response, ,) = HederaTokenService.mintToken(htsTokenAddress(), int64(uint64(_amountLD)), new bytes[](0));
        if (response != HederaTokenService.SUCCESS_CODE) {
            revert HTSMintFailed();
        }

        int256 transferResponse = HederaTokenService.transferToken(htsTokenAddress(), address(this), _to, int64(uint64(_amountLD)));
        if (transferResponse != HederaTokenService.SUCCESS_CODE) {
            revert HTSTransferFailed();
        }

        return _amountLD;
    }

    /**
     * @dev Public function to mint tokens
     * @param _amountLD The amount of tokens to mint in local decimals
     * @param to The address to mint tokens to
     * @return newTotalSupply The new total supply after minting
     * @return serialNumbers The serial numbers of the minted tokens
     */
    function mintTokenPublic(uint256 _amountLD, address to) 
        external 
        onlyOwner 
        onlyWhenTokenCreated
        returns (int64 newTotalSupply, int64[] memory serialNumbers) 
    {
        if (_amountLD > uint64(type(int64).max)) {
            revert AmountExceedsInt64Range();
        }

        int256 response;
        (response, newTotalSupply, serialNumbers) = HederaTokenService.mintToken(htsTokenAddress(), int64(uint64(_amountLD)), new bytes[](0));
        if (response != HederaTokenService.SUCCESS_CODE) {
            revert HTSMintFailed();
        }

        int256 transferResponse = HederaTokenService.transferToken(htsTokenAddress(), address(this), to, int64(uint64(_amountLD)));
        if (transferResponse != HederaTokenService.SUCCESS_CODE) {
            revert HTSTransferFailed();
        }

        emit MintedToken(newTotalSupply, _amountLD, to);
    }

    /**
     * @dev Public function to burn tokens
     * @param _amountLD The amount of tokens to burn in local decimals
     * @return responseCode The response code from the burn operation
     * @return newTotalSupply The new total supply after burning
     */
    function burnTokenPublic(uint256 _amountLD) 
        external 
        onlyWhenTokenCreated
        returns (int256 responseCode, int64 newTotalSupply) 
    {
        if (_amountLD > uint64(type(int64).max)) {
            revert AmountExceedsInt64Range();
        }

        int256 transferResponse = HederaTokenService.transferToken(htsTokenAddress(), msg.sender, address(this), int64(uint64(_amountLD)));
        if (transferResponse != HederaTokenService.SUCCESS_CODE) {
            revert HTSTransferFailed();
        }

        (responseCode, newTotalSupply) = HederaTokenService.burnToken(htsTokenAddress(), int64(uint64(_amountLD)), new int64[](0));
        if (responseCode != HederaTokenService.SUCCESS_CODE) {
            revert HTSBurnFailed();
        }

        emit BurnedToken(newTotalSupply, _amountLD, msg.sender);
    }

    /// @dev allows to send HBAR to contract for potential state rent
    receive() external payable {
    }
}

